// Logs → Cost tab — the token ECONOMICS, AS GRAPH SOURCE (epic #3604).
//
// The Sessions tab already says what each session cost. This says WHY, which is a different question
// and invisible there. Measured on the real store when this was written — 51 priced sessions,
// $3,452.75 total:
//
//   input             319,551
//   output         21,864,987
//   cache_creation 368,008,338
//   cache_read  5,691,747,795   ← 93.5% of every token the fleet has ever spent
//
// That ratio IS the economics, and no surface in the app said it. A dollar figure alone cannot be
// acted on; "almost everything you pay for is cache reads" can.
//
// A KNOWN ERROR IS RENDERED, NOT HIDDEN. The rollup charges one transcript to every pane that points
// at it — $260.81 of that $3,452.75 is double-counted, filed as
// `cost-double-counts-a-transcript-two-panes-share`. A cost screen quietly reporting a number 7.6%
// high is worse than one that reports it and says so, because nobody questions a total.
//
// Preview note: the rollup type is app-internal (unresolvable in this sandbox), so it and a sample
// fleet are inlined. Every prop still overrides the sample when composed by LogsWorkspace.
import { StatTile } from "@/shared/ui/data/StatTile";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Banner } from "@/shared/ui/feedback/Banner";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

/** One session's token + cost rollup — the `logs::Cost` shape. Snake_case ON THE WIRE. */
interface CostRow {
  session: string; model: string;
  input: number; output: number; cache_creation: number; cache_read: number; cost_usd: number;
}

/** The model a transcript reports when a message carries none — priced at zero, not a real model. */
export const SYNTHETIC = "<synthetic>";

const SAMPLE_ROWS: CostRow[] = [
  { session: "design-studio:designer", model: "claude-sonnet-5", input: 41000, output: 6100000, cache_creation: 92000000, cache_read: 1740000000, cost_usd: 1040.28 },
  { session: "algorithms-studio:librarian", model: "claude-sonnet-5", input: 18000, output: 2400000, cache_creation: 41000000, cache_read: 690000000, cost_usd: 413.49 },
  { session: "studio-code:director", model: "claude-opus-5", input: 9000, output: 410000, cache_creation: 8800000, cache_read: 121000000, cost_usd: 184.21 },
  { session: "planning_alpha", model: SYNTHETIC, input: 0, output: 0, cache_creation: 0, cache_read: 0, cost_usd: 0 },
];

/** Every token a row accounts for. */
export function rowTokens(r: CostRow): number {
  return r.input + r.output + r.cache_creation + r.cache_read;
}

/** Fleet totals, plus the share of all tokens that were CACHE READS — the number this tab exists for. */
export function costTotals(rows: CostRow[]) {
  const t = { input: 0, output: 0, cache_creation: 0, cache_read: 0, cost: 0 };
  for (const r of rows) {
    t.input += r.input; t.output += r.output;
    t.cache_creation += r.cache_creation; t.cache_read += r.cache_read;
    t.cost += r.cost_usd;
  }
  const tokens = t.input + t.output + t.cache_creation + t.cache_read;
  // Guard the divide: an empty fleet is 0%, not NaN%.
  return { ...t, tokens, cacheShare: tokens === 0 ? 0 : (t.cache_read / tokens) * 100 };
}

/** Per-model rollup, most expensive first. `<synthetic>` is kept — it is real rows, priced at zero,
 *  and dropping it would make the session count on this tab disagree with the Sessions tab. */
export function byModel(rows: CostRow[]): { model: string; sessions: number; tokens: number; cost: number }[] {
  const acc = new Map<string, { model: string; sessions: number; tokens: number; cost: number }>();
  for (const r of rows) {
    const e = acc.get(r.model) ?? { model: r.model, sessions: 0, tokens: 0, cost: 0 };
    e.sessions += 1; e.tokens += rowTokens(r); e.cost += r.cost_usd;
    acc.set(r.model, e);
  }
  return [...acc.values()].sort((a, b) => b.cost - a.cost || a.model.localeCompare(b.model));
}

/** Sessions charged an IDENTICAL token signature — the shape of the double-count. Reported rather
 *  than corrected: which half is wrong (the emitter's mapping, or the per-pane summing) is undecided,
 *  and silently dropping a row would be picking an answer. */
export function duplicateSignatures(rows: CostRow[]): { sessions: string[]; cost: number }[] {
  const by = new Map<string, CostRow[]>();
  for (const r of rows) {
    if (rowTokens(r) === 0) continue; // all-zero rows are not evidence of anything
    const k = [r.input, r.output, r.cache_creation, r.cache_read].join("/");
    by.set(k, [...(by.get(k) ?? []), r]);
  }
  return [...by.values()]
    .filter((g) => g.length > 1)
    .map((g) => ({ sessions: g.map((r) => r.session), cost: g.slice(1).reduce((n, r) => n + r.cost_usd, 0) }));
}

/** `1.7B` / `92.0M` / `41.0K` — a raw 5,691,747,795 is unreadable in a table cell. */
export function fmtTokens(n: number): string {
  const v = Number.isFinite(n) ? n : 0;
  if (v >= 1e9) return (v / 1e9).toFixed(1) + "B";
  if (v >= 1e6) return (v / 1e6).toFixed(1) + "M";
  if (v >= 1e3) return (v / 1e3).toFixed(1) + "K";
  return String(v);
}

/** `$1,234.56` — never `$NaN`. */
export function fmtUsd(n: number): string {
  const v = Number.isFinite(n) ? n : 0;
  return "$" + v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

export interface CostTabProps {
  rows?: CostRow[];
  loaded?: boolean;
}

export function CostTab({ rows = SAMPLE_ROWS, loaded = true }: CostTabProps) {
  const t = costTotals(rows);
  const models = byModel(rows);
  const dupes = duplicateSignatures(rows);
  const dupeCost = dupes.reduce((n, d) => n + d.cost, 0);
  const ranked = [...rows].sort((a, b) => b.cost_usd - a.cost_usd || a.session.localeCompare(b.session));

  const MCOLS = "1.4fr 74px 90px 96px";
  const SCOLS = "1.6fr 128px 68px 68px 74px 74px 84px";

  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="cost" v={fmtUsd(t.cost)} tone="accent" sub={rows.length + " priced sessions"} />
        <StatTile k="tokens" v={fmtTokens(t.tokens)} sub="across every counter" />
        <StatTile k="cache reads" v={t.cacheShare.toFixed(1) + "%"} sub="of all tokens" />
        <StatTile k="output" v={fmtTokens(t.output)} sub="what the models wrote" />
      </Box>

      {/* Reported, never quietly netted out. */}
      {dupes.length > 0 && (
        <Banner tone="warn" style={{ marginBottom: 12 }}>
          <Text as="div" size={12}>
            <strong>{fmtUsd(dupeCost)} of this total is counted more than once.</strong>{" "}
            {dupes.length === 1 ? "Two sessions share" : dupes.length + " groups of sessions share"} an
            identical token signature, which happens when panes point at the same transcript — the
            rollup charges each of them. Shown as reported rather than corrected, because which half is
            wrong is undecided. Tracked as{" "}
            <Text as="span" mono size={11}>cost-double-counts-a-transcript-two-panes-share</Text>.
          </Text>
        </Banner>
      )}

      {rows.length === 0 ? (
        <EmptyState
          iconVariant="dashed" icon="◷" size="sm"
          title={loaded ? "No priced sessions yet" : "Reading the transcripts…"}
          description="A session is priced once its transcript records token usage. Sessions that never called a model do not appear here."
        />
      ) : (
        <>
          <Text as="div" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em", marginBottom: 7 }}>by model</Text>
          <Box border="soft" radius={7} style={{ overflow: "hidden", marginBottom: 16 }}>
            <Box style={{ display: "grid", gridTemplateColumns: MCOLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
              <Box as="span">model</Box>
              <Box as="span" style={{ textAlign: "right" }}>sessions</Box>
              <Box as="span" style={{ textAlign: "right" }}>tokens</Box>
              <Box as="span" style={{ textAlign: "right" }}>cost</Box>
            </Box>
            {models.map((m, i) => (
              <Box key={m.model} style={{ display: "grid", gridTemplateColumns: MCOLS, gap: 10, alignItems: "center", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
                {/* `<synthetic>` is not a model anyone chose — it is what a transcript reports for a
                    message with no model, priced at zero. Labelling it plainly keeps it from reading
                    as a real (and mysteriously free) model. */}
                {m.model === SYNTHETIC ? (
                  <Text as="span" mono size={11} tone="dim" style={{ fontStyle: "italic" }}>no model recorded</Text>
                ) : (
                  <Text as="span" mono size={11}>{m.model}</Text>
                )}
                <Text as="span" mono size={11} tone="muted" style={{ textAlign: "right" }}>{m.sessions}</Text>
                <Text as="span" mono size={11} tone="muted" style={{ textAlign: "right" }}>{fmtTokens(m.tokens)}</Text>
                <Text as="span" mono size={11} style={{ textAlign: "right", color: m.cost > 0 ? "var(--accent)" : "var(--fg-dim)" }}>{m.cost > 0 ? fmtUsd(m.cost) : "—"}</Text>
              </Box>
            ))}
          </Box>

          <Row align="baseline" gap={8} style={{ marginBottom: 7 }}>
            <Text as="span" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em" }}>by session</Text>
            <Text as="span" mono size={10} tone="dim">· most expensive first</Text>
          </Row>
          <Box border="soft" radius={7} style={{ overflow: "hidden" }}>
            <Box style={{ display: "grid", gridTemplateColumns: SCOLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
              <Box as="span">session</Box><Box as="span">model</Box>
              <Box as="span" style={{ textAlign: "right" }}>in</Box>
              <Box as="span" style={{ textAlign: "right" }}>out</Box>
              <Box as="span" style={{ textAlign: "right" }}>cache w</Box>
              <Box as="span" style={{ textAlign: "right" }}>cache r</Box>
              <Box as="span" style={{ textAlign: "right" }}>cost</Box>
            </Box>
            {ranked.map((r, i) => (
              <Box key={r.session} style={{ display: "grid", gridTemplateColumns: SCOLS, gap: 10, alignItems: "center", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)", opacity: r.cost_usd === 0 ? 0.55 : 1 }}>
                <Text as="span" mono size={11} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.session}</Text>
                <Text as="span" mono size={10.5} tone="dim" style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.model === SYNTHETIC ? "—" : r.model}</Text>
                <Text as="span" mono size={10.5} tone="muted" style={{ textAlign: "right" }}>{fmtTokens(r.input)}</Text>
                <Text as="span" mono size={10.5} tone="muted" style={{ textAlign: "right" }}>{fmtTokens(r.output)}</Text>
                <Text as="span" mono size={10.5} tone="muted" style={{ textAlign: "right" }}>{fmtTokens(r.cache_creation)}</Text>
                <Text as="span" mono size={10.5} tone="muted" style={{ textAlign: "right" }}>{fmtTokens(r.cache_read)}</Text>
                <Text as="span" mono size={11} style={{ textAlign: "right", color: r.cost_usd > 0 ? "var(--accent)" : "var(--fg-dim)" }}>{r.cost_usd > 0 ? fmtUsd(r.cost_usd) : "—"}</Text>
              </Box>
            ))}
          </Box>
        </>
      )}
    </Box>
  );
}

