// The Logs → Cost tab — the token economics.
//
// Carried ON the record, so it runs against the copy that actually mounts.
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import {
  CostTab, SYNTHETIC, rowTokens, costTotals, byModel, duplicateSignatures, fmtTokens, fmtUsd,
} from "./CostTab";

const ROWS = [
  { session: "a", model: "claude-sonnet-5", input: 100, output: 900, cache_creation: 1000, cache_read: 8000, cost_usd: 10 },
  { session: "b", model: "claude-opus-5", input: 100, output: 100, cache_creation: 100, cache_read: 700, cost_usd: 5 },
  { session: "c", model: SYNTHETIC, input: 0, output: 0, cache_creation: 0, cache_read: 0, cost_usd: 0 },
];

/** The real shape of the double-count: two sessions, identical counters. */
const DUPED = [
  ...ROWS,
  { session: "d1", model: "claude-sonnet-5", input: 7, output: 7, cache_creation: 7, cache_read: 7, cost_usd: 260.81 },
  { session: "d2", model: "claude-sonnet-5", input: 7, output: 7, cache_creation: 7, cache_read: 7, cost_usd: 260.81 },
];

describe("pure helpers", () => {
  it("rowTokens sums all four counters", () => {
    expect(rowTokens(ROWS[0])).toBe(10000);
  });

  it("costTotals reports the CACHE SHARE — the number this tab exists for", () => {
    const t = costTotals(ROWS);
    expect(t.cost).toBe(15);
    expect(t.tokens).toBe(11000);
    expect(t.cacheShare).toBeCloseTo((8700 / 11000) * 100, 5);
  });

  it("an empty fleet is 0%, not NaN%", () => {
    // The share is a divide, and a fresh install has no rows at all.
    expect(costTotals([]).cacheShare).toBe(0);
    expect(costTotals([ROWS[2]]).cacheShare).toBe(0); // all-zero row: still a divide by zero
  });

  it("byModel ranks by cost and KEEPS the synthetic bucket", () => {
    // Dropping it would make this tab's session count disagree with the Sessions tab.
    expect(byModel(ROWS).map((m) => m.model)).toEqual(["claude-sonnet-5", "claude-opus-5", SYNTHETIC]);
    expect(byModel(ROWS).find((m) => m.model === SYNTHETIC)!.sessions).toBe(1);
  });

  it("byModel breaks a cost tie on the model name, so the table does not shuffle", () => {
    const tied = [
      { session: "x", model: "zeta", input: 1, output: 0, cache_creation: 0, cache_read: 0, cost_usd: 3 },
      { session: "y", model: "alpha", input: 1, output: 0, cache_creation: 0, cache_read: 0, cost_usd: 3 },
    ];
    expect(byModel(tied).map((m) => m.model)).toEqual(["alpha", "zeta"]);
  });

  it("duplicateSignatures finds identical token counters and charges only the EXTRA copies", () => {
    // Two sessions at $260.81 each means $260.81 is the over-count, not $521.62 — one of them is real.
    const d = duplicateSignatures(DUPED);
    expect(d).toHaveLength(1);
    expect(d[0].sessions.sort()).toEqual(["d1", "d2"]);
    expect(d[0].cost).toBeCloseTo(260.81, 2);
  });

  it("does NOT flag all-zero rows as duplicates of each other", () => {
    // Every un-priced session has 0/0/0/0. Treating those as a double-count would report a fleet-wide
    // error that does not exist.
    const zeros = [
      { session: "z1", model: SYNTHETIC, input: 0, output: 0, cache_creation: 0, cache_read: 0, cost_usd: 0 },
      { session: "z2", model: SYNTHETIC, input: 0, output: 0, cache_creation: 0, cache_read: 0, cost_usd: 0 },
    ];
    expect(duplicateSignatures(zeros)).toEqual([]);
  });

  it("fmtTokens keeps a billion readable, and never renders NaN", () => {
    expect(fmtTokens(5691747795)).toBe("5.7B");
    expect(fmtTokens(368008338)).toBe("368.0M");
    expect(fmtTokens(319551)).toBe("319.6K");
    expect(fmtTokens(42)).toBe("42");
    expect(fmtTokens(NaN)).toBe("0");
  });

  it("fmtUsd never renders NaN", () => {
    expect(fmtUsd(3452.75)).toContain("3,452.75");
    expect(fmtUsd(undefined as unknown as number)).toBe("$0.00");
  });
});

describe("CostTab", () => {
  it("leads with the cache share, not just the dollar figure", () => {
    render(<CostTab rows={ROWS} />);
    expect(screen.getByText("cache reads")).toBeInTheDocument();
    expect(screen.getByText("79.1%")).toBeInTheDocument();
  });

  it("SURFACES the known double-count instead of netting it out silently", () => {
    render(<CostTab rows={DUPED} />);
    expect(screen.getByText(/of this total is counted more than once/)).toBeInTheDocument();
    expect(screen.getByText("cost-double-counts-a-transcript-two-panes-share")).toBeInTheDocument();
    // …and the headline total still includes it, because correcting it would be picking a side.
    expect(screen.getByText("$536.62")).toBeInTheDocument();
  });

  it("says nothing about duplicates when there are none", () => {
    render(<CostTab rows={ROWS} />);
    expect(screen.queryByText(/counted more than once/)).toBeNull();
  });

  it("labels the synthetic bucket rather than passing it off as a model", () => {
    render(<CostTab rows={ROWS} />);
    expect(screen.getByText("no model recorded")).toBeInTheDocument();
  });

  it("ranks sessions by cost, most expensive first", () => {
    const { container } = render(<CostTab rows={ROWS} />);
    const html = container.innerHTML;
    expect(html.indexOf(">a<")).toBeLessThan(html.indexOf(">b<"));
  });

  it("an empty store is an empty STATE, and loading says loading", () => {
    const { rerender } = render(<CostTab rows={[]} loaded />);
    expect(screen.getByText("No priced sessions yet")).toBeInTheDocument();
    rerender(<CostTab rows={[]} loaded={false} />);
    expect(screen.getByText("Reading the transcripts…")).toBeInTheDocument();
  });
});
